sp_widget.client_script:
api.controller = function($scope, $timeout) {

    var c = this;

    function initializeMap() {

        if (typeof L === 'undefined') {
            loadLeaflet();
            return;
        }

        var mapElement =
            document.getElementById('environment-pollution-map');

        if (!mapElement)
            return;

        if (mapElement._leaflet_id)
            return;

        var locations = c.data.locations || [];

        var map = L.map(mapElement).setView(
            [11.1271, 78.6569],
            7
        );

        L.tileLayer(
            'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
            {
                attribution: '&copy; OpenStreetMap contributors'
            }
        ).addTo(map);

        var bounds = [];

        locations.forEach(function(item) {

            var marker = L.marker([
                item.latitude,
                item.longitude
            ]).addTo(map);

            marker.bindPopup(
                '<div style="min-width:190px;">' +
                '<strong>Pollution Incident</strong><br><br>' +
                '<b>Location:</b> ' +
                escapeHtml(item.location) +
                '<br>' +
                '<b>Complaint:</b> ' +
                escapeHtml(item.complaint) +
                '</div>'
            );

            bounds.push([
                item.latitude,
                item.longitude
            ]);
        });

        // Automatically zoom to actual database records
        if (bounds.length > 0) {

            map.fitBounds(bounds, {
                padding: [30, 30]
            });

        }

        $timeout(function() {
            map.invalidateSize();
        }, 500);
    }


    function loadLeaflet() {

        if (document.getElementById('leaflet-js')) {
            return;
        }

        var script = document.createElement('script');

        script.id = 'leaflet-js';

        script.src =
            'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';

        script.onload = function() {
            initializeMap();
        };

        document.head.appendChild(script);
    }


    function escapeHtml(value) {

        if (!value)
            return '';

        return String(value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#039;');
    }


    $timeout(function() {
        initializeMap();
    }, 500);

};

sp_widget.css:
.environment-map {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px;
    margin: 20px 0;
    box-shadow: 0 3px 12px rgba(0,0,0,0.10);
