    font-weight: 600;
}

sp_widget.script:
(function() {

    data.locations = [];

    var TABLE = 'x_snc_environmen_0_location_coordinates';

    var gr = new GlideRecord(TABLE);

    if (!gr.isValid()) {
        data.error = 'Location Coordinates table not found';
        return;
    }

    gr.query();

    while (gr.next()) {

        // Find latitude field from existing table
        var latField = '';

        if (gr.isValidField('latitude'))
            latField = 'latitude';
        else if (gr.isValidField('lat'))
            latField = 'lat';
        else if (gr.isValidField('u_latitude'))
            latField = 'u_latitude';

        // Find longitude field
        var lngField = '';

        if (gr.isValidField('longitude'))
            lngField = 'longitude';
        else if (gr.isValidField('lng'))
            lngField = 'lng';
        else if (gr.isValidField('lon'))
            lngField = 'lon';
        else if (gr.isValidField('u_longitude'))
            lngField = 'u_longitude';

        if (!latField || !lngField)
            continue;

        var lat = parseFloat(gr.getValue(latField));
        var lng = parseFloat(gr.getValue(lngField));

        if (isNaN(lat) || isNaN(lng))
            continue;

        var location = '';

        if (gr.isValidField('location'))
            location = gr.getDisplayValue('location');

        else if (gr.isValidField('location_name'))
            location = gr.getDisplayValue('location_name');

        else if (gr.isValidField('u_location'))
            location = gr.getDisplayValue('u_location');


        var complaint = '';

        if (gr.isValidField('complaint'))
            complaint = gr.getDisplayValue('complaint');

        else if (gr.isValidField('complaint_id'))
            complaint = gr.getDisplayValue('complaint_id');

        else if (gr.isValidField('u_complaint'))
            complaint = gr.getDisplayValue('u_complaint');


        data.locations.push({
            latitude: lat,
            longitude: lng,
            location: location || 'Environmental Location',
            complaint: complaint || 'Pollution Incident'
        });
    }

})();
